// Verwacht payload als { "x": 0.25, "y": -0.7 }

let data = msg.payload;

// 1) Buffer → string
if (Buffer.isBuffer(data)) {
    data = data.toString();
}

// 2) String → JSON parsen
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.warn("Invalid JSON in joystick payload: " + data);
        return null;
    }
}

// 3) Controleren dat het echt een object is
if (!data || typeof data !== "object") {
    node.warn("Joystick payload is not an object: " + JSON.stringify(data));
    return null;
}

// 4) x en y moeten bestaan en numbers zijn
if (typeof data.x !== "number" || typeof data.y !== "number") {
    node.warn("Invalid joystick payload: missing or non-number x/y in " + JSON.stringify(data));
    return null;
}

// 5) Optionele range-check: beide tussen -1 en 1
if (data.x < -1 || data.x > 1 || data.y < -1 || data.y > 1) {
    node.warn("Joystick values out of range in " + JSON.stringify(data));
    return null;
}

// 6) Schrijf x en y weg naar Influx
msg.measurement = "controller/joystick";

// optioneel: tags toevoegen (bv. bron)
msg.tags = {
    source: "simulator"
};

msg.payload = {
    x: data.x,
    y: data.y
};

return msg;

// Verwacht payload als { "button": "A", "pressed": true }
// of { "button": "A", "pressed": 1 }

let data = msg.payload;

if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.warn("Invalid JSON in button payload");
        return null;
    }
}

// "button" moet bestaan
if (!data.button) {
    node.warn("Invalid button payload: missing button");
    return null;
}

// pressed mag boolean of 0/1 zijn → convert
if (typeof data.pressed === "number") {
    data.pressed = data.pressed === 1;
}

if (typeof data.pressed !== "boolean") {
    node.warn("Invalid button payload: pressed is not boolean or 0/1");
    return null;
}

// Voor InfluxDB
msg.measurement = "button_state";
msg.payload = {
    button: data.button,
    value: data.pressed ? 1 : 0   // 1 bij pressed, anders 0
};

return msg;
